#include <stdio.h>
#include <string.h>

int is_fair(const char *s, int n) {
    int count_A = 0, count_B = 0, max_diff = 0;
    for (int i = 0; i < n; i++) {
        if (s[i] == '1') {
            count_A++;
        } else {
            count_B++;
        }
        max_diff = (max_diff > abs(count_A - count_B)) ? max_diff : abs(count_A - count_B);
    }
    return max_diff <= 1;
}

int main() {
    int T;
    scanf("%d", &T);
    while (T--) {
        int N;
        scanf("%d", &N);
        char S[N + 1];
        scanf("%s", S);

        if (is_fair(S, N)) {
            printf("YES\n");
        } else {
