            justify-content: space-between;
            align-items: center; /* Optional: vertically centers the buttons if the container has extra height */
            padding: 10px; /* Optional: adds some padding to the container */
        }

        .button {
            padding: 10px 20px;
            background-color: #007bff;
            color: white;
            border: none;
