```java
import java.util.List;
import java.util.Optional;

public class ListChecker {

    public static <T> T checkList(List<T> list) {
        // Convert the list to a stream and count the number of elements
        long count = list.stream().count();

        if (count > 1) {
            // If there are more than one elements, throw an exception
            throw new IllegalStateException("List contains more than one entry");
        } else if (count == 1) {
            // If there is exactly one element, return it
            return list.stream().findFirst().orElseThrow(() -> new IllegalStateException("Unexpected error"));
        } else {
            // If there are no elements, return null
            return null;
        }
    }

    public static void main(String[] args) {
        // Test cases
        List<String> list1 = List.of(); // Empty list
        List<String> list2 = List.of("single"); // Single entry
        List<String> list3 = List.of("one", "two"); // More than one entry

        try {
            System.out.println("List 1 result: " +："+ checkList(list1)); // Should print: List 1 result: null
            System.out.println("List 2 result: " + checkList(list2)); // Should print: List 2 result: single
            System.out.println("List 3 result: " + checkList(list3)); // Should throw an exception
        } catch (IllegalStateException e) {
            System.out.println("Exception: " + e.getMessage());
        }
    }
}
```

### Explanation:
1. **Count the Elements**: The method first converts the list to a stream and counts the number of elements using `stream().count()`.
2. **Check the Count**:
   - If the count is greater than 1, it throws an `IllegalStateException`.
   - If the count is exactly 1, it returns the single element using `stream().findFirst().orElseThrow()`.
   - If the count is 0, it returns `null`.

### Test Cases:
- **Empty List**: The method returns `null`.
- **Single Entry**: The method returns the single entry.
- **More than One Entry**: The method throws an `IllegalStateException`.

You can run the `main` method to see the behavior of the `checkList` method with different test cases.

Certainly! Implementing a reverb effect using Kotlin and JNI (Java Native Interface) involves several steps. We'll need to write a native C/C++ function that applies the reverb effect and then call this function from Kotlin. Below is a step-by-step guide to achieve this.

### Step 1: Set Up Your Project

1. **Create a new Kotlin project** in Android Studio.
2. **Enable C++ support** in your project:
   - Go to `File > Project Structure > Modules > app > Properties`.
   - Set `Language version` and `API level` as needed.
   - Go to `File > Project Structure > Modules > app > Dependencies`.
   - Add `NDK` to the dependencies.

### Step 2: Write the Native C++ Code

Create a new C++ file in the `cpp` directory of your project. For example, `reverb.cpp`.

```cpp
#include <jni.h>
#include <android/log.h>
#include <cstring>
#include <cmath>

#define LOG_TAG "ReverbJNI"
#define LOGI(...) __android_log_print(ANDROID_LOG_INFO, LOG_TAG, __VA_ARGS__)

extern "C" {

// Function to apply reverb effect
void applyReverb(short* input, short* output, int length, float wetLevel, float dryLevel, float delay, float decay) {
    int bufferLength = static_cast<int>(delay * 44100.0); // Assuming 44.1kHz sample rate
    short buffer[bufferLength];
    std::memset(buffer, 0, bufferLength * sizeof(short));

    for (int i = 0; i < length; ++i) {
        int bufferIndex = (i + bufferLength - 1) % bufferLength;
        float drySample = input[i];
        float wetSample = buffer[bufferIndex] * decay;
        float outputSample = drySample * dryLevel + wetSample * wetLevel;

        output[i] = static_cast<short>(outputSample);
        buffer[i % bufferLength] = outputSample;
    }
}

// JNI function to call the reverb effect
JNIEXPORT void JNICALL Java_com_example_reverb_ReverbNative_applyReverb(
        JNIEnv* env, jobject /* this */, jshortArray input, jshortArray output, jint length, jfloat wetLevel, jfloat dryLevel, jfloat delay, jfloat decay) {
    jshort* inputSamples = env->GetShortArrayElements(input, nullptr);
    jshort* outputSamples = env->GetShortArrayElements(output, nullptr);

    applyReverb(inputSamples, outputSamples, length, wetLevel, dryLevel, delay, decay);

    env->ReleaseShortArrayElements(input, inputSamples, 0);
    env->ReleaseShortArrayElements(output, outputSamples, 0);
}

}
```

### Step 3: Create the Kotlin Code

Create a Kotlin file, for example, `ReverbNative.kt`.

```kotlin
package com.example.reverb

external fun applyReverb(input: ShortArray, output: ShortArray, length: Int, wetLevel: Float, dryLevel: Float, delay: Float, decay: Float)

class ReverbNative {
    companion object {
        init {
            System.loadLibrary("reverb")
        }
    }

    fun applyReverb(input: ShortArray, output: ShortArray, wetLevel: Float, dryLevel: Float, delay: Float, decay: Float) {
        applyReverb(input, output, input.size, wetLevel, dryLevel, delay, decay)
    }
}
```

### Step 4: Use the Reverb Function in Your Kotlin Code

You can now use the `ReverbNative` class to apply the reverb effect to your audio data.

```kotlin
package com.example.reverb

import android.media.AudioFormat
import android.media.AudioRecord
import android.media.MediaRecorder
import android.os.Bundle
import androidx.appcompat.app.AppCompatActivity
import java.util.concurrent.ExecutorService
import java.util.concurrent.Executors

class MainActivity : AppCompatActivity() {

    private lateinit var reverbNative: ReverbNative
    private lateinit var audioRecord: AudioRecord
    private lateinit var inputBuffer: ShortArray
    private lateinit var outputBuffer: ShortArray
    private lateinit var executor: ExecutorService

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        reverbNative = ReverbNative()

        val sampleRate = 44100
        val bufferSize = AudioRecord.getMinBufferSize(sampleRate, AudioFormat.CHANNEL_IN_MONO, AudioFormat.ENCODING_PCM_16BIT)
        audioRecord = AudioRecord(MediaRecorder.AudioSource.MIC, sampleRate, AudioFormat.CHANNEL_IN_MONO, AudioFormat.ENCODING_PCM_16BIT, bufferSize)
        inputBuffer = ShortArray(bufferSize / 2)
        outputBuffer = ShortArray(bufferSize / 2)
        executor = Executors.newSingleThreadExecutor()

        audioRecord.startRecording()
        startReverbProcessing()
    }

    private fun startReverbProcessing() {
        executor.execute {
            while (true) {
                val readSize = audioRecord.read(inputBuffer, 0, inputBuffer.size)
                if (readSize > 0) {
                    reverbNative.applyReverb(inputBuffer, outputBuffer, 0.5f, 0.5f, 0.5f, 0.9f)
                    // Process outputBuffer or send it to output
                }
            }
        }
    }

    override fun onDestroy() {
        super.onDestroy()
        audioRecord.stop()
        audioRecord.release()
        executor.shutdown()
    }
}
```

### Step 5: Configure the `CMakeLists.txt` File

Make sure you have the `CMakeLists.txt` file set up to compile your C++ code.

