### FavoritesManager Class

```php
<?php

namespace App\Favorites;

use App\Models\User;
use App\Models\Favorite;
use Illuminate\Support\Facades\Auth;
use Illuminate\Session\Store;

class FavoritesManager
{
    protected $user;
    protected $session;

    public function __construct(User $user = null, Store $session = null)
    {
        $this->user = $user ?? Auth::user();
        $this->session = $session ?? app('session.store');
    }

    public function addFavorite(string $name): bool
    {
        if ($this->user) {
            // Save to database for logged-in users
            $favorite = new Favorite([
                'user_id' => $this->user->id,
                'name' => $name,
            ]);
            return $favorite->save();
        } else {
            // Save to session for guests
            $favorites = $this->session->get('favorites', []);
            if (!in_array($name, $favorites)) {
                $favorites[] = $name;
                $this->session->put('favorites', $favorites);
                return true;
            }
        }
        return false;
    }

    public function removeFavorite(string $name): bool
    {
        if ($this->user) {
            // Remove from database for logged-in users
            return Favorite::where('user_id', $this->user->id)
                ->where('name', $name)
                ->delete();
        } else {
            // Remove from session for guests
            $favorites = $this->session->get('favorites', []);
            $index = array_search($name, $favorites);
            if ($index !== false) {
                unset($favorites[$index]);
                $this->session->put('favorites', array_values($favorites));
                return true;
            }
        }
        return false;
    }

    public function getFavorites(): array
    {
        if ($this->user) {
            // Get from database for logged-in users
            return $this->user->favorites()->pluck('name')->toArray();
        } else {
            // Get from session for guests
            return $this->session->get('favorites', []);
        }
    }
}
```

