### Metal Compute Kernel for Gaussian Blur

```metal
#include <metal_stdlib>
using namespace metal;

// Gaussian blur kernel size
constant int kKernelSize = 5;
constant float kSigma = 1.0;

// Precomputed Gaussian weights
constant float kGaussianWeights[kKernelSize] = {
    0.06136, 0.24477, 0.38774, 0.24477, 0.06136
};

// Texture sampler
constant sampler s;

// Compute kernel
kernel void gaussian_blur(
    texture2d<float, access::read> inTexture [[ texture(0) ]],
    texture2d<float, access::write> outTexture [[ texture(1) ]],
    uint2 gid [[ thread_position_in_grid ]],
    uint2 size [[ threadgroup_position_in_grid ]],
    uint2 gridSize [[ grid_size ]])
{
    // Check if the current thread is within the image bounds
    if (gid.x >= gridSize.x || gid.y >= gridSize.y) {
        return;
    }

    // Initialize the accumulator for the blurred pixel
    float4 blurredPixel = float4(0.0);

    // Apply the Gaussian blur in the X direction
    for (int x = -kKernelSize / 2; x <= kKernelSize / 2; ++x) {
        int sampleX = clamp(gid.x + x, 0, gridSize.x - 1);
        float4 sample = inTexture.read(uint2(sampleX, gid.y));
        blurredPixel += sample * kGaussianWeights[x + kKernelSize / 2];
    }

    // Write the blurred pixel to the output texture
    outTexture.write(blurredPixel, gid);
}
```

### Explanation

1. **Gaussian Weights**: The `kGaussianWeights` array contains precomputed Gaussian weights for a 5x5 kernel with a standard deviation (`sigma`) of 1.0. These weights are used to apply the Gaussian blur.

2. **Texture Samplers**: The `sampler` is used to sample the texture. In this example, we are using the default sampler.

3. **Compute Kernel**: The `gaussian_blur` kernel function is the main function that performs the Gaussian blur. It takes the input texture, output texture, and thread position as parameters.

4. **Boundary Check**: The kernel first checks if the current thread is within the image bounds to avoid out-of-bounds access.

5. **Gaussian Blur**: The kernel applies the Gaussian blur in the X direction by summing the weighted contributions of the neighboring pixels. The `clamp` function ensures that the sample coordinates stay within the image bounds.

6. **Output**: The blurred pixel is written to the output texture.

### Note

- This kernel only applies the Gaussian blur in the X direction. To apply a full 2D Gaussian blur, you would need to apply the blur in the Y direction as well. This can be done by either applying the kernel twice (once for each direction) or by combining the X and Y blurs in a single kernel.
- The `kKernelSize` and `kSigma` can be adjusted to change the size and spread of the Gaussian blur.

### Example of Applying the Kernel in Metal

To use this kernel in a Metal program, you would typically set up a compute pipeline, create buffers for the input and output textures, and dispatch the kernel to the GPU. Here is a simplified example of how you might set this up in Swift:

```swift
import Metal
import MetalKit

class GaussianBlur {
    let device: MTLDevice
    let commandQueue: MTLCommandQueue
    let computePipelineState: MTLComputePipelineState
    let inTexture: MTLTexture
    let outTexture: MTLTexture

    init(device: MTLDevice, inTexture: MTLTexture, outTexture: MTLTexture) throws {
        self.device = device
        self.commandQueue = device.makeCommandQueue()!
        self.inTexture = inTexture
        self.outTexture = outTexture

        let library = try device.makeDefaultLibrary(bundle: Bundle.main)
        let kernelFunction = library.makeFunction(name: "gaussian_blur")
        self.computePipelineState = try device.makeComputePipelineState(function: kernelFunction!)
    }

    func apply() {
        let commandBuffer = commandQueue.makeCommandBuffer()!
        let computeEncoder = commandBuffer.makeComputeCommandEncoder()!
        computeEncoder.setComputePipelineState(computePipelineState)
        computeEncoder.setTexture(inTexture, index: 0)
        computeEncoder.setTexture(outTexture, index: 1)

        let threadGroupSize = MTLSize(width: 16, height: 16, depth: 1)
        let threadGroups = MTLSize(width: (inTexture.width + threadGroupSize.width - 1) / threadGroupSize.width,
                                   height: (inTexture.height + threadGroupSize.height - 1) / threadGroupSize.height,
                                   depth: 1)

        computeEncoder.dispatchThreadgroups(threadGroups, threadsPerThreadgroup: threadGroupSize)
        computeEncoder.endEncoding()
        commandBuffer.commit()
        commandBuffer.waitUntilCompleted()
    }
}
```

This class sets up the Metal compute pipeline, encodes the compute commands, and dispatches the kernel to the GPU. You can create an instance of this class and call the `apply` method to apply the Gaussian blur to your image.

