<?php
namespace App;

use App\Controllers\UserController;
use App\Controllers\GroupController;
use App\Database\Connection;
use App\Database\UserRepository;
use App\Database\GroupRepository;
use Psr\Container\ContainerInterface;
use Slim\App;
use Slim\Routing\RouteCollectorProxy;

class Routes
{
    public static function setupRoutes(App $app, ContainerInterface $container)
    {
        $connection = Connection::getConnection();
        $userRepository = new UserRepository($connection);
        $groupRepository = new GroupRepository($connection);

        $app->group('/scim', function (RouteCollectorProxy $group) use ($userRepository, $groupRepository) {
            $group->get('/Users', UserController::class . ':getUsers');
            $group->get('/Users/{id}', UserController::class . ':getUser');
            $group->post('/Users', UserController::class . ':createUser');
            $group->patch('/Users/{id}', UserController::class . ':updateUser');
            $group->delete('/Users/{id}', UserController::class . ':deleteUser');

            $group->get('/Groups', GroupController::class . ':getGroups');
            $group->get('/Groups/{id}', GroupController::class . ':getGroup');
            $group->post('/Groups', GroupController::class . ':createGroup');
            $group->patch('/Groups/{id}', GroupController::class . ':updateGroup');
            $group->delete('/Groups/{id}', GroupController::class . ':deleteGroup');
        });
    }
}
```

