Creating a simple Connect-4 game in Python can be a fun and educational project. Below is a basic implementation of the Connect-4 game. This implementation will be a command-line version where you can play against another human player.

```python
class Connect4:
    def __init__(self, rows=6, cols=7):
        self.rows = rows
        self.cols = cols
        self.board = [[' ' for _ in range(cols)] for _ in range(rows)]
        self.current_player = 'X'

    def print_board(self):
        print("  " + " ".join(str(i) for i in range(1, self.cols + 1)))
        for row in self.board:
            print("|" + "|".join(row) + "|")
        print(" " + "-" * (2 * self.cols - 1))

    def drop_piece(self, col):
        for row in range(self.rows - 1, -1, -1):
            if self.board[row][col] == ' ':
                self.board[row][col] = self.current_player
                return True
        return False

    def check_winner(self):
        # Check horizontal
        for row in range(self.rows):
            for col in range(self.cols - 3):
                if self.board[row][col] == self.board[row][col + 1] == self.board[row][col + 2] == self.board[row][col + 3] != ' ':
                    return True

        # Check vertical
        for col in range(self.cols):
            for row in range(self.rows - 3):
                if self.board[row][col] == self.board[row + 1][col] == self.board[row + 2][col] == self.board[row + 3][col] != ' ':
                    return True

        # Check diagonal (top-left to bottom-right)
        for row in range(self.rows - 3):
            for col in range(self.cols - 3):
                if self.board[row][col] == self.board[row + 1][col + 1] == self.board[row + 2][col + 2] == self.board[row + 3][col + 3] != ' ':
                    return True

        # Check diagonal (bottom-left to top-right)
        for row in range(3, self.rows):
            for col in range(self.cols - 3):
                if self.board[row][col] == self.board[row - 1][col + 1] == self.board[row - 2][col + 2] == self.board[row - 3][col + 3] != ' ':
                    return True

        return False

    def is_full(self):
        return all(self.board[0][col] != ' ' for col in range(self.cols))

    def switch_player(self):
        self.current_player = 'O' if self.current_player == 'X' else 'X'

    def play(self):
        while True:
            self.print_board()
            col = input(f"Player {self.current_player}, choose a column (1-{self.cols}): ")
            if not col.isdigit() or not (1 <= int(col) <= self.cols):
                print("Invalid input. Please choose a valid column.")
                continue
            col = int(col) - 1
            if not self.drop_piece(col):
                print("Column is full. Please choose another column.")
                continue

            if self.check_winner():
                self.print_board()
                print(f"Player {self.current_player} wins!")
                break

            if self.is_full():
                self.print_board()
                print("The game is a draw!")
                break

            self.switch_player()

