```rust
use regex::Regex;
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::process::Command;
use tokio::task;

#[tokio::main]
async fn main() -> io::Result<()> {
    let file = File::open("urls.txt")?;
    let reader = BufReader::new(file);

    let youtube_regex = Regex::new(r"https://www\.youtube\.com/watch\?v=[\w-]+").unwrap();

    let mut youtube_urls = Vec::new();
    let mut other_urls = Vec::new();

    for line in reader.lines() {
        let url = line?;
        if youtube_regex.is_match(&url) {
            youtube_urls.push(url);
        } else {
            other_urls.push(url);
        }
    }

    println!("YouTube URLs:");
    for url in &youtube_urls {
        println!("{}", url);
    }

    println!("\nOther URLs:");
    for url in &other_urls {
        println!("{}", url);
    }

    let download_tasks: Vec<_> = youtube_urls
        .into_iter()
        .map(|url| task::spawn(download_youtube_video(url)))
        .collect();

    for task in download_tasks {
        task.await??;
    }

    Ok(())
}

async fn download_youtube_video(url: String) -> io::Result<()> {
    println!("Downloading: {}", url);
    let output = Command::new("yt-dlp")
        .arg(&url)
        .output()
        .await?;

    if !output.status.success() {
        eprintln!("Failed to download: {}", url);
        eprintln!("Error: {}", String::from_utf8_lossy(&output.stderr));
        return Err(io::Error::new(io::ErrorKind::Other, "Download failed"));
    }

    println!("Downloaded: {}", url);
    Ok(())
}
```

### Explanation:

1. **Reading the File**: The program reads the URLs from `urls.txt` line by line.
2. **Regex Matching**: It uses a regular expression to match YouTube URLs.
3. **Separating URLs**: It separates the URLs into two vectors: `youtube_urls` and `other_urls`.
