        xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Sierpinski Triangle" Height="450" Width="800">
    <Grid>
        <Canvas x:Name="Canvas" Background="White"/>
    </Grid>
</Window>
```

### Step 3: Add C# Code-Behind to Generate the Sierpinski Triangle
Open `MainWindow.xaml.cs` and add the necessary code to draw the Sierpinski Triangle.

```csharp
using System.Windows;
using System.Windows.Media;
using System.Windows.Shapes;

namespace SierpinskiTriangle
{
    public partial class MainWindow : Window
    {
        public MainWindow()
        {
            InitializeComponent();
            DrawSierpinskiTriangle(new Point(100, 350), new Point(400, 50), new Point(700, 350), 5);
        }

        private void DrawSierpinskiTriangle(Point p1, Point p2, Point p3, int depth)
        {
            if (depth == 0)
            {
                DrawTriangle(p1, p2, p3);
            }
            else
            {
                Point p12 = new Point((p1.X + p2.X) / 2, (p1.Y + p2.Y) / 2);
                Point p23 = new Point((p2.X + p3.X) / 2, (p2.Y + p3.Y) / 2);
                Point p31 = new Point((p3.X + p1.X) / 2, (p3.Y + p1.Y) / 2);

                DrawSierpinskiTriangle(p1, p12, p31, depth - 1);
                DrawSierpinskiTriangle(p12, p2, p23, depth - 1);
                DrawSierpinskiTriangle(p31, p23, p3, depth - 1);
            }
        }

        private void DrawTriangle(Point p1, Point p2, Point p3)
        {
            Polygon triangle = new Polygon
            {
                Points = new PointCollection { p1, p2, p3 },
                Fill = Brushes.Black
            };
            Canvas.Children.Add(triangle);
        }
    }
}
```

### Explanation
1. **XAML**: The `MainWindow.xaml` file contains a `Canvas` where the Sierpinski Triangle will be drawn.
2. **C# Code-Behind**:
   - **Constructor**: The `MainWindow` constructor calls the `DrawSierpinskiTriangle` method with the initial points and depth.
   - **DrawSierpinskiTriangle**: This method is a recursive function that divides the triangle into smaller triangles and calls itself for each smaller triangle until the desired depth is reached.
   - **DrawTriangle**: This method creates a `Polygon` and adds it to the `Canvas`.

### Step 4: Run the Application
1. Press `F5` to run the application.
2. You should see a Sierpinski Triangle drawn on the window.

### Customization
- **Depth**: You can adjust the depth parameter in the `DrawSierpinskiTriangle` method call to increase or decrease the detail of the fractal.
- **Colors**: You can change the `Fill` property of the `Polygon` to use different colors for the triangles.

